package com.hms.website;
import com.hms.tenancy.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/public/hospitals/{tenantSlug}/pages") public class PublicPageController { private final TenantRepository tenants; private final WebsitePageRepository pages; public PublicPageController(TenantRepository t,WebsitePageRepository p){tenants=t;pages=p;} @GetMapping public List<WebsitePage> list(@PathVariable String tenantSlug){return pages.findAllByTenantIdAndStatusOrderByTitleAsc(tenant(tenantSlug),PageStatus.PUBLISHED);} @GetMapping("/{slug}") public WebsitePage page(@PathVariable String tenantSlug,@PathVariable String slug){return pages.findByTenantIdAndSlug(tenant(tenantSlug),slug).filter(p->p.getStatus()==PageStatus.PUBLISHED).orElseThrow(()->new IllegalArgumentException("Published page not found"));} private UUID tenant(String slug){return tenants.findBySlug(slug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(slug));} }
